using FleetOps.Modules.Documents;
using FleetOps.Modules.Fleet;
using FleetOps.People;
using FleetOps.Kernel;
using Xunit;

namespace FleetOps.Tests;

public sealed class ReadinessTests : IAsyncLifetime
{
    private readonly VehicleApiFactory factory = new();

    public ValueTask InitializeAsync() => factory.InitializeAsync();
    public ValueTask DisposeAsync() => factory.DisposeAsync();

    [Fact] public async Task Truck_with_all_documents_is_usable() { var v = await Truck(); await ReadinessTestSupport.AddAllVehicleDocuments(factory, v.Id); Assert.True((await ReadinessTestSupport.Vehicle(factory, v.Id)).Usable); }
    [Fact] public async Task Truck_with_no_documents_is_not_usable_but_stays_active() { var v = await Truck(); var r = await ReadinessTestSupport.Vehicle(factory, v.Id); Assert.False(r.Usable); Assert.Equal(ReadinessShownStatus.Active, r.ShownStatus); Assert.Contains(r.Causes, x => x.Code == ReadinessCauseCode.DocumentMissing); }
    [Fact] public async Task Truck_with_expired_hu_is_off_road() { var v = await Truck(); await ReadinessTestSupport.AddAllVehicleDocuments(factory, v.Id); await ReadinessTestSupport.AddDocument(factory, DocumentOwnerType.Vehicle, v.Id, DocumentType.HuReport, new DateOnly(2026, 11, 5)); var r = await ReadinessTestSupport.Vehicle(factory, v.Id); Assert.Equal(ReadinessShownStatus.OffRoad, r.ShownStatus); Assert.Contains(r.Causes, x => x.DocumentType == "hu_report"); }
    [Fact] public async Task Uploaded_renewal_does_not_clear_an_expired_document() { var v = await Truck(); await ReadinessTestSupport.AddDocument(factory, DocumentOwnerType.Vehicle, v.Id, DocumentType.HuReport, new DateOnly(2026, 11, 5)); await ReadinessTestSupport.AddDocument(factory, DocumentOwnerType.Vehicle, v.Id, DocumentType.HuReport, new DateOnly(2027, 1, 1), DocumentStatus.Uploaded, 2); Assert.Contains((await ReadinessTestSupport.Vehicle(factory, v.Id)).Causes, x => x.Code == ReadinessCauseCode.DocumentExpired); }
    [Fact] public async Task Rejected_document_counts_as_missing() { var v = await Truck(); await ReadinessTestSupport.AddDocument(factory, DocumentOwnerType.Vehicle, v.Id, DocumentType.HuReport, new DateOnly(2027, 1, 1), DocumentStatus.Rejected); Assert.Contains((await ReadinessTestSupport.Vehicle(factory, v.Id)).Causes, x => x.Code == ReadinessCauseCode.DocumentMissing); }
    [Fact] public async Task Expiring_today_is_usable_today_and_blocked_tomorrow() { var v = await Truck(); await ReadinessTestSupport.AddAllVehicleDocuments(factory, v.Id, new DateOnly(2026, 11, 6)); Assert.True((await ReadinessTestSupport.Vehicle(factory, v.Id, new DateOnly(2026, 11, 6))).Usable); Assert.False((await ReadinessTestSupport.Vehicle(factory, v.Id, new DateOnly(2026, 11, 7))).Usable); }
    [Fact] public async Task Driver_expiring_today_can_drive_today_and_not_tomorrow() { var id = Guid.NewGuid(); await ReadinessTestSupport.AddEmployee(factory, id); await ReadinessTestSupport.AddAllDriverDocuments(factory, id, new DateOnly(2026, 11, 6)); Assert.True((await ReadinessTestSupport.Driver(factory, id, new DateOnly(2026, 11, 6))).CanDrive); Assert.False((await ReadinessTestSupport.Driver(factory, id, new DateOnly(2026, 11, 7))).CanDrive); }
    [Fact] public async Task Light_truck_needs_no_sp_report() { var v = await Truck(7000); await ReadinessTestSupport.AddAllVehicleDocuments(factory, v.Id); await using var connection = await factory.DirectConnection(); await using var command = new Npgsql.NpgsqlCommand("delete from fleetops.documents where owner_id = @id and type = 'sp_report'", connection); command.Parameters.AddWithValue("id", v.Id); await command.ExecuteNonQueryAsync(); Assert.True((await ReadinessTestSupport.Vehicle(factory, v.Id)).Usable); }
    [Fact] public async Task Retired_vehicle_is_not_usable() { var v = await Truck(); await ReadinessTestSupport.AddAllVehicleDocuments(factory, v.Id); await ReadinessTestSupport.SetVehicle(factory, v.Id, VehicleStatus.Retired); var r = await ReadinessTestSupport.Vehicle(factory, v.Id); Assert.False(r.Usable); Assert.Contains(r.Causes, x => x.Code == ReadinessCauseCode.Retired); }
    [Fact] public async Task Manual_off_road_blocks_and_clearing_a_document_does_not_undo_it() { var v = await Truck(); await ReadinessTestSupport.AddAllVehicleDocuments(factory, v.Id); await ReadinessTestSupport.SetVehicle(factory, v.Id, VehicleStatus.Active, true); Assert.Contains((await ReadinessTestSupport.Vehicle(factory, v.Id)).Causes, x => x.Code == ReadinessCauseCode.ManualOffRoad); }
    [Fact] public async Task Clearing_manual_off_road_leaves_an_expired_document_blocking() { var v = await Truck(); await ReadinessTestSupport.AddAllVehicleDocuments(factory, v.Id, new DateOnly(2026, 11, 5)); await ReadinessTestSupport.SetVehicle(factory, v.Id, VehicleStatus.Active, false); Assert.False((await ReadinessTestSupport.Vehicle(factory, v.Id)).Usable); }
    [Fact] public async Task Suspended_driver_cannot_drive() { var id = await DriverWithDocuments(EmployeeStatus.Suspended); Assert.False((await ReadinessTestSupport.Driver(factory, id)).CanDrive); }
    [Fact] public async Task Left_driver_cannot_drive() { var id = await DriverWithDocuments(EmployeeStatus.Left); Assert.False((await ReadinessTestSupport.Driver(factory, id)).CanDrive); }
    [Fact] public async Task Employee_without_the_driver_role_cannot_drive() { var id = Guid.NewGuid(); await ReadinessTestSupport.AddEmployee(factory, id, "[]"); await ReadinessTestSupport.AddAllDriverDocuments(factory, id); Assert.False((await ReadinessTestSupport.Driver(factory, id)).CanDrive); }
    [Fact] public async Task Adr_certificate_does_not_block_yet() { var id = Guid.NewGuid(); await ReadinessTestSupport.AddEmployee(factory, id); await ReadinessTestSupport.AddAllDriverDocuments(factory, id); await ReadinessTestSupport.AddDocument(factory, DocumentOwnerType.Employee, id, DocumentType.AdrCertificate, new DateOnly(2026, 11, 5)); Assert.True((await ReadinessTestSupport.Driver(factory, id)).CanDrive); }
    [Fact] public async Task Readiness_has_no_tables() { await using var c = await factory.DirectConnection(); await using var q = new Npgsql.NpgsqlCommand("select count(*) from information_schema.tables where table_schema = 'fleetops' and table_name ilike '%readiness%'", c); Assert.Equal(0L, (long)(await q.ExecuteScalarAsync())!); Assert.DoesNotContain(typeof(FleetOps.Migrations.FleetOpsDbContext).GetProperties(), x => x.PropertyType.Name.Contains("Readiness", StringComparison.OrdinalIgnoreCase)); }
    [Fact] public async Task Vehicle_status_column_holds_only_lifecycle_values() { var v = await Truck(); await ReadinessTestSupport.AddDocument(factory, DocumentOwnerType.Vehicle, v.Id, DocumentType.HuReport, new DateOnly(2026, 11, 5)); await ReadinessTestSupport.SetVehicle(factory, v.Id, VehicleStatus.Active, true); await using var c = await factory.DirectConnection(); await using var q = new Npgsql.NpgsqlCommand("select status from fleetops.vehicles where id = @id", c); q.Parameters.AddWithValue("id", v.Id); Assert.Equal("Active", await q.ExecuteScalarAsync()); }

    private async Task<VehicleDetail> Truck(int weight = 8000) => await factory.CreateTruck(factory.AsDispatcher(), grossWeightKg: weight);
    private async Task<Guid> DriverWithDocuments(EmployeeStatus status) { var id = Guid.NewGuid(); await ReadinessTestSupport.AddEmployee(factory, id, status: status); await ReadinessTestSupport.AddAllDriverDocuments(factory, id); return id; }
}
